from pathlib import Path
import csv,json
p=Path(__file__).parent
rows=list(csv.DictReader((p/'matched_annual_growth.csv').open(encoding='utf-8-sig')))
data=[dict(region=r['region'],year=int(r['year']),value=float(r['growth_pct']),n=int(r['matched_complexes'])) for r in rows]
html='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>지역별 연간 집값 상승률</title><style>body{margin:0;background:#f6f4ef;color:#173348;font-family:"Malgun Gothic",sans-serif;padding:28px}h1{font-size:26px;margin-bottom:8px}p{color:#546973;line-height:1.7}.box{background:white;border-radius:16px;padding:20px;overflow:auto}svg{width:100%;min-width:850px;height:auto;display:block}label{margin-right:24px;font-weight:bold;cursor:pointer}.tip{min-height:28px;margin:12px 0;font-size:16px}.note{font-size:13px}circle{cursor:crosshair}</style><h1>지역별 연간 집값 상승률</h1><p>2006년 거래를 출발점으로, 2007~2025년의 전년 대비 변화를 비교합니다.</p><div id="legend"></div><div class="tip" id="tip">점에 마우스를 올리면 상승률과 매칭 단지 수가 표시됩니다.</div><div class="box"><svg id="chart" viewBox="0 0 1200 530" role="img" aria-label="서울 경기 인천 연간 상승률 꺾은선 차트"></svg></div><p class="note">단위: % · 누적 상승률이 아닌 각 연도의 전년 대비 변화율입니다.<br>동일 단지·동일 면적, 두 해 각각 거래 5건 이상인 표본을 비교한 자체 분석입니다. 연평균 거래가격 기준이며 공식 가격지수와 다릅니다. 층·수리 상태·거래 시점 차이는 미조정입니다.<br>2026년은 부분 자료여서 제외했습니다.</p><script>const data=DATA;const colors={'서울':'#286cda','경기':'#d17b16','인천':'#24816c'};const s=document.getElementById('chart'), ns='http://www.w3.org/2000/svg';function add(tag,a,t){let e=document.createElementNS(ns,tag);for(let k in a)e.setAttribute(k,a[k]);if(t!==undefined)e.textContent=t;s.appendChild(e);return e}const xmin=2007,xmax=2025;const lo=Math.floor(Math.min(...data.map(d=>d.value))/10)*10,hi=Math.ceil(Math.max(...data.map(d=>d.value))/10)*10;const X=y=>80+(y-xmin)/(xmax-xmin)*1080,Y=v=>460-(v-lo)/(hi-lo)*420;for(let v=lo;v<=hi;v+=10){add('line',{x1:80,x2:1160,y1:Y(v),y2:Y(v),stroke:v===0?'#526777':'#e3e6e8','stroke-width':v===0?2:1,'stroke-dasharray':v===0?'6 4':'none'});add('text',{x:66,y:Y(v)+5,'text-anchor':'end','font-size':14,fill:'#546973'},v+'%')}for(let y=xmin;y<=xmax;y++)add('text',{x:X(y),y:492,'text-anchor':'middle','font-size':13,fill:'#546973'},y);for(let reg of Object.keys(colors)){let group=document.createElementNS(ns,'g');s.appendChild(group);let a=data.filter(d=>d.region===reg&&d.n>=30).sort((a,b)=>a.year-b.year);let path=add('path',{d:a.map((d,i)=>(i&&d.year===a[i-1].year+1?'L':'M')+X(d.year)+','+Y(d.value)).join(' '),fill:'none',stroke:colors[reg],'stroke-width':3});group.appendChild(path);for(let d of a){let c=add('circle',{cx:X(d.year),cy:Y(d.value),r:5,fill:colors[reg],stroke:'white','stroke-width':2,tabindex:0});group.appendChild(c);let label=reg+' '+d.year+'년: '+(d.value>=0?'+':'')+d.value.toFixed(1)+'% · 매칭 단지 '+d.n.toLocaleString()+'개';c.setAttribute('aria-label',label);c.addEventListener('mouseenter',()=>document.getElementById('tip').textContent=label);c.addEventListener('focus',()=>document.getElementById('tip').textContent=label);let title=document.createElementNS(ns,'title');title.textContent=label;c.appendChild(title)}let l=document.createElement('label'),cb=document.createElement('input');cb.type='checkbox';cb.checked=true;cb.onchange=()=>group.style.display=cb.checked?'':'none';l.style.color=colors[reg];l.append(cb,document.createTextNode(' '+reg));document.getElementById('legend').appendChild(l)}</script></html>'''.replace('DATA',json.dumps(data,ensure_ascii=False))
(p/'chart_view.html').write_text(html,encoding='utf8');print('Updated chart_view.html:',len(data),'points')
